function getRandomCode(){$("#rondomCodeImg").attr("src","/WeixinService/buildimageservlet.xhtml")}function queryTradeInfoByTradeNo(){var n=getUrlParameter("serialno");if(n==null||n==""){errorRemark("没有查询到订单");redirectUrl("/WeixinService/business/query/orderList.shtml");return}$.ajax({async:!1,url:"/WeixinService/business/queryTradeInfoByTradeNo.xhtml",data:{serialno:n},dataType:"json",cache:!1,type:"post",error:function(){},success:function(n){if(n!=null&&n.returnCode=="0000"){var t=n.dto;$("#serialno").val(t.serialno);$("#tradeAcco").val(t.tradeacco);$("#fundId").val(t.fundInfoDtoV2.fundId);$("#orderType").val(t.orderType);$("#subamt").val(t.subamt);$("#moneyZero").val(t.fundInfoDtoV2.money);queryMyBankCard()}else if(n!=null&&n.returnCode=="9000"){errorRemark("没有查询到订单");redirectUrl("/WeixinService/business/query/orderList.shtml");return}}})}function modifyAppointRequest(){var i=$("#serialno").val(),u=$("#tradeAcco").val(),r=$("#bankInfo li.act").attr("data-tradeacco"),n=$("#tPassWord").val(),t=$("#randomCode").val(),f=parseFloat($("#subamt").val()),e=parseFloat($("#moneyZero").val()),o=parseFloat($("#bankInfo li.act").attr("data-balance"));if(o<=0&&f<e){errorRemark("该银行卡号无产品在途金额<br />请更换银行卡");return}if(u==r){errorRemark("待更换银行卡不能和原订单银行卡一致");return}if(n==null||n==""){errorRemark("请输入安全码");return}if(t==null||t==""){errorRemark("请输入验证码");return}$.ajax({async:!1,url:"/WeixinService/business/modifyAppointRequest.xhtml",data:{serialno:i,tradeAcco:r,tPassWord:n,randomCode:t},dataType:"json",cache:!1,type:"POST",error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(n){if(n.returnCode!=null&&n.returnCode=="0000")errorRemark("修改成功"),window.setTimeout("redirectUrl('/WeixinService/business/query/orderDetail.shtml?serialno="+i+"');",1e3);else{if(n.returnCode=="USR-1I01"){errorRemark("错误次数过多<br>3小时后重试");$("#randomCode,#tPassWord").val("");$("#rondomCodeImg").click();return}if(n.returnCode=="USR-1I02"){n.tPwdErrCount==1?(errorRemark("安全码有误"),$("#tPassWord").val("")):n.tPwdErrCount>1&&n.tPwdErrCount<6&&errorRemark("安全码有误<br>还有"+(6-parseInt(n.tPwdErrCount))+"次机会");$("#randomCode,#tPassWord").val("");$("#rondomCodeImg").click();return}errorRemark(n.returnMsg);$("#randomCode").val("");$("#rondomCodeImg").click();return}}})}function queryMyBankCard(){var n=$("#tradeAcco").val(),t=$("#fundId").val();$.ajax({async:!1,url:"/WeixinService/business/queryMyBankCardNo.xhtml",data:{fundid:t},dataType:"json",cache:!1,type:"POST",error:function(){errorRemark("网络繁忙，请稍后再试。")},success:function(t){var i="";t.returnCode=="0000"&&(i="",$.each(t.tradeAcctlist,function(t,r){r.tradeAcco==n?($("#payCardInfo").html(replaceStr2(r.bankAccoDisplay,4,4)+"("+r.bankNm+")"),i+="<li class='act' "):i+="<li ";i+="id='card_"+t+"' data-bankNm='"+r.bankNm+"' data-bankNo='"+r.bankNo+"' data-bankAccoDisplay='"+r.bankAccoDisplay+"' data-tradeAcco='"+r.tradeAcco+"' data-balance='"+r.balance+"' ";i+=" onclick='selectCard(\"card_"+t+"\")'>";i+=r.bankNm+"（尾号"+(r.bankAccoDisplay||0).substr(r.bankAccoDisplay.length-4)+"）<span>";i+=r.payMode!=null&&r.payMode=="7"?"仅支持线下汇款<\/span><\/li>":r.payMode!=null&&r.payMode=="6"?"仅支持线下汇款<\/span><\/li>":r.payMode!=null&&r.payMode=="5"?"仅支持线下汇款<\/span><\/li>":r.payMode!=null&&r.payMode=="4"?"仅支持线下汇款<\/span><\/li>":r.payMode!=null&&r.payMode=="3"?"仅支持线下汇款<\/span><\/li>":r.payMode!=null&&r.payMode=="2"?"仅支持线下汇款<\/span><\/li>":r.payMode!=null&&r.payMode=="1"?"仅支持线下汇款<\/span><\/li>":"仅支持线下汇款<\/span><\/li>"}),$("#bankInfo").html(i))}})}function selectCard(n){$("#bankInfo li").removeClass("act");$("#"+n).addClass("act");$("#payCardInfo").html(replaceStr2($("#"+n).attr("data-bankAccoDisplay"),4,4)+"("+$("#"+n).attr("data-bankNm")+")");getUserRequest("modify-bankcard-select");setTimeout("$('#showCards').hide();",500)}function addBank(){var n=getUrlParameter("serialno");window.location.href="/WeixinService/business/bank/addBank.shtml?type=1&serialno="+n}$(document).ready(function(){$(".header .top-a h2").html("更换支付银行");document.title="更换支付银行";var n=$(window).height(),t=$(".buy_btn").height(),i=n-t;$(".buy_btn").css("top",i);getRandomCode();queryTradeInfoByTradeNo();getUserRequest("modify-bankcard")});$(".cover-bg").on("click",function(){setTimeout("$('.cover-bg').hide()",500)})